INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','لماذا لا تبتعد الأرض عن مدارها حول الشمس؟','["لأن الأرض لا تتحرك", "لأن القمر يجذب الأرض", "بسبب دوران الشمس حول الأرض", "لأن قوة الجاذبية والقصور الذاتي تُبقيانها في مدارها"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','أيّ الظواهر التالية تحدث بسبب دوران الأرض حول الشمس؟','["تعاقب الليل والنهار", "أطوار القمر", "خسوف القمر", "الفصول الأربعة"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','جسم صخري أو فلزي صغير يدخل الغلاف الجوي ويحترق قبل ارتطامه بسطح الأرض ويظهر كخط لامع في السماء:','["النيزك", "الكويكب", "الشهاب", "المذنّب"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','تدور الكواكب حول الشمس بسبب قوة الجذب، وتزداد هذه القوة كلما:','["نقصت كتلة الكوكب وابتعد عن الشمس", "نقصت كتلة الكوكب واقترب من الشمس", "زادت كتلة الكوكب وابتعد عن الشمس", "زادت كتلة الكوكب واقترب من الشمس"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','ما شكل مجرة درب التبانة التي تقع فيها مجموعتنا الشمسية؟','["غير منتظم", "بيضاوي", "لولبي", "إهليلجي"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','أدّت ندى صلاة الظهر وقت الزوال، ويعود الفضل بعد الله في معرفة أوقات الصلاة إلى:','["التوقيت المعياري", "حركة الشمس الظاهرية", "أطوار القمر", "المجموعات النجمية"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',11,'الفلك والفضاء','إذا كان طول ظل عمود أقل كثيرًا من طوله الحقيقي، فإن الوقت تقريبًا:','["بعد العشاء", "بعد شروق الشمس قليلًا", "الصباح الباكر", "الظهر"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','ماذا نسمي إمكانية سريان الكهرباء في أكثر من مسار؟','["دائرة واحدة", "التوصيل على التوالي", "التوصيل على التساوي", "التوصيل على التوازي"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','يُستخدم الرفع المغناطيسي في صنع بعض القطارات لأنها على درجة عالية من الكفاءة، وذلك بسبب:','["قوة جذب الأجسام", "التجاذب بين الأقطاب", "انعدام الجاذبية", "عدم وجود احتكاك"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','في المولدات الكهربائية يحدث تحوّل للطاقة من:','["حرارية إلى ميكانيكية", "نووية إلى كهربائية", "كهربائية إلى حركية", "حركية إلى كهربائية"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','أيّ الأدوات التالية تحتاج إلى المغناطيس في عملها؟','["مفتاح كهرباء", "بطارية", "مصباح", "مولد كهربائي"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','بماذا يختلف المغناطيس الكهربائي عن المغناطيس الدائم؟','["له خاصية الجذب المغناطيسي", "يجذب بعض الفلزات", "يمكن تشغيله وإيقاف عمله", "يمكن أن يسحب ويدفع"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','تراكم الشحنات الكهربائية على سطح الأجسام يمثل تعريفًا لـ:','["التيار الكهربائي", "الكهرباء الساكنة", "التأريض", "الدائرة الكهربائية"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','تراكم الغبار على شاشة التلفاز يحدث بسبب:','["الكهرباء الساكنة", "المقاومة الكهربائية", "توليد الكهرباء", "التيار الكهربائي"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','تتولد الكهرباء نتيجة جسيمات صغيرة جدًا لا يمكن رؤيتها تسمى:','["الشحنات الكهربائية", "التيار الكهربائي", "الدوائر الكهربائية", "التفريغ الكهربائي"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','لمس طالب مقبض الباب الحديدي فأحسّ بلسعة كهربائية خفيفة، وذلك بسبب:','["الجهد الكهربائي", "الاحتكاك الكهربائي", "التيار الكهربائي", "التفريغ الكهربائي"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','لاحظ معلم أن الكرة 1 والكرة 2 تتجاذبان، بينما الكرة 1 والكرة 3 تتنافران. أيّ العبارات صحيحة؟','["الكرتان 2 و3 مختلفتان في الشحنة", "الكرتان 2 و3 متشابهتان في الشحنة", "جميع الكرات متشابهة في الشحنة", "الكرتان 1 و3 مختلفتان في الشحنة"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',12,'الكهرباء والمغناطيسية','أيّ مما يلي يؤدي إلى حدوث البرق؟','["سقوط قطرات الماء من الغيمة بسرعة", "اختلاف الحرارة بين قمة الغيمة وقاعدتها", "انتقال الشحنات الكهربائية بين طرفي الغيمة أو بين غيمتين", "مرور أشعة الشمس خلال قطرات الماء"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','تُغطّى أسلاك الكهرباء بطبقة من المطاط أو البلاستيك لأن كليهما:','["ينجذب للمغناطيس", "لا يوصل الكهرباء", "مصنوع من المعدن", "يوصل الكهرباء"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','لماذا يُستخدم النحاس في الدوائر الكهربائية؟','["لأنه رخيص الثمن", "لقدرته على التوصيل الجيد", "لسهولة الحصول عليه", "لأنه متوفر بكثرة"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','أيّ المواد التالية ستضيء المصباح عندما تُستخدم لتوصيل الدائرة الكهربائية؟','["البلاستيك", "الخشب", "النحاس", "الزجاج"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','لماذا تُوصل المصابيح في المنزل على التوازي؟','["حتى لا تستهلك الكهرباء", "لترشيد الكهرباء", "حتى تكون إضاءتها أشد", "حتى لا يتوقف التيار عند تعطل أحد المصابيح"]',3);
