INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','عند رش برادة الحديد على مغناطيس تتشكل خطوط تمثل اتجاهات القوى المغناطيسية حوله، تسمى:','["المجال المغناطيسي", "القطب المغناطيسي", "المغناطيس الكهربائي", "المجال الكهربائي"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','عند قطع مغناطيس إلى جزأين، ماذا يحدث؟','["يصبح أحدهما قطبًا شماليًّا والآخر جنوبيًّا", "يفقد كل منهما خاصيته", "يصبحان مغناطيسين جديدين لكل منهما قطبان", "يصبح كل منهما مغناطيسًا بقطب واحد"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','أين يكون تأثير المغناطيس أقوى؟','["ثابت في جميع أجزائه", "عند القطبين", "عند الطرف الشمالي فقط", "في المنتصف"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','كلما كانت خطوط المجال المغناطيسي أقرب إلى بعضها، فإن القوة المغناطيسية تكون:','["ثابتة لا تتغير", "منعدمة", "أقوى", "أضعف"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','لفّ فهد سلكًا نحاسيًّا معزولًا حول مسمار من الحديد ثم وصل طرفيه ببطارية، ما قام به فهد هو عمل:','["مغناطيس كهربائي", "مولد كهربائي", "محرك كهربائي", "قاطع كهربائي"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',13,'الكهرباء والمغناطيسية','كيف يمكنك زيادة قوة جذب مغناطيس كهربائي صنعته؟','["وضع خشب بدل المسمار", "تقليل لفات السلك", "استخدام بطارية أضعف", "زيادة لفات السلك"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'الكهرباء والمغناطيسية','في الجرس الكهربائي، ما الدور الذي يقوم به المغناطيس الكهربائي؟','["يزيد من قوة البطارية", "يصدر الصوت مباشرة", "يجذب المطرقة عند مرور التيار فتطرق الجرس", "يمنع اهتزاز الجرس"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'الكهرباء والمغناطيسية','في المحركات الكهربائية يحدث تحوّل للطاقة من:','["كهربائية إلى حركية", "حرارية إلى ميكانيكية", "نووية إلى كهربائية", "كهربائية إلى حرارية"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'المادة وخصائصها','أيّ مما يلي ليس من الخصائص الفيزيائية؟','["الكثافة", "القساوة", "الصدأ", "درجة الغليان"]',2);
