INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'المادة وخصائصها','اختبر طلاب مادة بيضاء مجهولة وسجلوا ملاحظاتهم في الجدول، أيّ الاختبارات يكشف عن خاصية كيميائية؟','["1", "2", "3", "4"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'المادة وخصائصها','أيّ الخيارات التالية لا يُصنّف من المواد؟','["الماء", "الرمل", "الحرارة", "الهواء"]',2);
