INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'المادة وخصائصها','كم كثافة صخرة كتلتها 70 جرامًا وحجمها 10 سم³؟','["7 جم/سم³", "0.8 جم/سم³", "0.7 جم/سم³", "8 جم/سم³"]',0);
