INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'المادة وخصائصها','ما الذي يحدث عند ارتفاع درجة حرارة جسم ما؟','["ينكمش", "يتكثف", "يتقلص", "يتمدد"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',14,'المادة وخصائصها','الوصف المناسب لتغير المادة عند تبخرها هو أنها تتغير من:','["الصلب إلى السائل", "السائل إلى الغاز", "الغاز إلى السائل", "السائل إلى الصلب"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المادة وخصائصها','إذا أحضرت قطع الثلج ثم عرّضتها للحرارة، فإن حالتها تتغير من:','["السائلة إلى الصلبة", "الغازية إلى السائلة", "الصلبة إلى السائلة", "السائلة إلى الغازية"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المادة وخصائصها','أيّ التحولات أدناه يتطلب فقد طاقة؟','["الانصهار", "التبخر", "الغليان", "التجمد"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المادة وخصائصها','لا ترتفع درجة حرارة مادة صلبة رغم استمرار تسخينها؛ وذلك لأنها:','["تمر بعملية الانصهار", "تمر بعملية التبخر", "لم تمتص الحرارة", "تفقد حرارة"]',0);
