INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المخاليط والمحاليل','عملية الترشيح تُستخدم لفصل مواد:','["غازية عن سائلة", "صلبة عن صلبة", "سائلة عن سائلة", "صلبة عن سائلة"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المخاليط والمحاليل','حسب الجدول، أيّ الخيارات التالية يمكن تصنيفه من المحاليل؟','["مخلوط 4", "مخلوط 1", "مخلوط 3", "مخلوط 2"]',2);
