INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المخاليط والمحاليل','أيّ المصطلحات التالية يعبّر عما ستحصل عليه عند إذابة السكر في الشاي؟','["مركب", "محلول", "عنصر", "جزيء"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المخاليط والمحاليل','أيّ من المواد التالية يُعدّ محلولًا؟','["مسحوق الطباشير", "ملح الطعام الصلب", "برادة الحديد", "السبيكة"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المخاليط والمحاليل','أيّ المخاليط التالية يحتوي على مواد لا تذوب تمامًا ولا تترسب، مما يجعله مثالًا على المخلوط الغروي؟','["الزيت والماء", "الشاي", "العصير الطبيعي مع اللب", "الكريمة المخفوقة"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',15,'المخاليط والمحاليل','ما نوع المخلوط الذي يترسب فيه الطين في الماء بعد فترة؟','["محلول متجانس", "مستحلب", "معلّق", "غروي"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'المخاليط والمحاليل','مادة تحوّل لون ورقة تباع الشمس (الكاشف) إلى اللون الأحمر:','["الماء النقي", "المنظّف المنزلي", "عصير الليمون", "الصابون"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'المخاليط والمحاليل','أيّ المواد التالية يذوب في الماء؟','["السكر", "برادة الحديد", "الرمل", "نشارة الخشب"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'المخاليط والمحاليل','إذا اختلط مسحوق الفحم وبرادة الحديد، فأيّ أداة مناسبة للفصل بينهما؟','["ورق ترشيح", "قمع", "مغناطيس", "شمعة"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'المخاليط والمحاليل','يُستخدم المغناطيس في فصل المخاليط التي تحتوي إحدى مكوناتها على:','["الألومنيوم", "الحديد", "البلاستيك", "الخشب"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'المخاليط والمحاليل','أحضرت مريم 30 جم من الطماطم و30 جم من الخيار و20 جم من الخس لصنع سلطة، وبعد تقطيعها وخلطها وزنتها فكان الوزن:','["60 جم", "70 جم", "80 جم", "100 جم"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'الذرة والعناصر','ماذا نسمي الجسيمات سالبة الشحنة التي تدور حول نواة الذرة؟','["الإلكترونات", "البروتونات", "الفوتونات", "النيوترونات"]',0);
