INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',16,'الذرة والعناصر','لدى أحمد فلز نقي صلب لامع، يتفاعل ببطء مع المواد الأخرى. إلى أيّ مجموعة ينتمي في الجدول الدوري؟','["الفلزات القلوية الأرضية", "الفلزات القلوية", "أشباه الفلزات", "الفلزات الانتقالية"]',3);
