INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',17,'الذرة والعناصر','ذرة الأكسجين تحتوي على 8 بروتونات و8 نيوترونات، ما عددها الذري؟','["4", "12", "8", "16"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',17,'الذرة والعناصر','مادة لا يمكن طرقها وتشكيلها مثل اليود، هل تُصنّف فلزية أم لا فلزية؟','["لا فلزية؛ لأنها غير قابلة للتشكيل", "فلزية؛ لأنها قابلة للطرق", "لا فلزية؛ لأنها قابلة للتشكيل", "فلزية؛ لأنها غير قابلة للتشكيل"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',17,'الذرة والعناصر','ماذا يحدث عند تقسيم قطعة من عنصر البورون إلى نصفين؟','["يحتفظ كلاهما بخصائص العنصر", "يفقدان خصائصهما", "يصبح أحدهما فلزًا والآخر لا فلزًا", "يتحول كل نصف إلى عنصر مختلف"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',17,'الذرة والعناصر','عندما ترتبط الذرات معًا تشكّل ما يسمى:','["الخلية", "الذرة", "الجزيء", "الطاقة"]',2);
