INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',18,'تصنيف المخلوقات الحية','أيّ ممالك المخلوقات الحية تضم مخلوقات لبعضها خصائص المملكة النباتية ولبعضها خصائص المملكة الحيوانية؟','["الفطريات", "البدائيات", "الطلائعيات", "البكتيريا"]',2);
