INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',18,'الخلية وتراكيبها','أيّ التراكيب التالية يتم فيها تصنيع الغذاء في الخلية النباتية؟','["الميتوكندريا", "الريبوسومات", "البلاستيدات الخضراء", "الشبكة الإندوبلازمية"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'الخلية وتراكيبها','سأل المعلم طلابه عن الفرق بين الخلية النباتية والحيوانية، فأيّهم إجابته صحيحة؟','["خالد", "محمد", "فهد", "عمر"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'الخلية وتراكيبها','يريد طالب تجربة انتقال المواد بالخاصية الأسموزية عبر غشاء رقيق، أيّ المواد سينفذ؟','["الماء", "السكر", "النيتروجين", "الأكسجين"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'الخلية وتراكيبها','عملية تحدث في الخلية يُستعمل فيها الأكسجين:','["البناء الضوئي", "التخمر", "التنفس الخلوي", "البلعمة"]',2);
