INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'التكيف والبقاء','لماذا يكون لون الضبّ مشابهًا للون بيئته التي يعيش فيها؟','["ليحصل على الغذاء", "ليحتمي من أشعة الشمس", "ليختفي من الأعداء", "ليتكاثر"]',2);
