INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'التكيف والبقاء','يتكيف الجربوع مع منطقته فيخرج ليلًا للبحث عن طعامه، إنه يعيش في:','["الأراضي الرطبة", "الصحاري", "الأراضي العشبية", "التندرا"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'الوراثة والصفات','أيّ الأشكال التالية هو من أشكال التكاثر الجنسي؟','["الاقتران", "الانشطار الثنائي", "التبرعم", "الانقسام"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'الوراثة والصفات','تختلف ألوان البشرة بين الطلاب في مدرستك بسبب:','["اختلاف بيئاتهم", "انتقال العدوى البكتيرية", "انتقال هذه الصفة من آبائهم", "نوع غذائهم"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',19,'الوراثة والصفات','الخميرة تتكاثر بنمو بروز صغير على الخلية الأم، ماذا يسمّى هذا النوع من التكاثر؟','["الاقتران", "الانشطار", "التبرعم", "الانقسام"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',20,'الوراثة والصفات','إذا كان لكلا الأبوين غمازات، ولكنهما يحملان جين الصفة المتنحية، فأيّ العبارات صحيحة؟','["لا يُشترط أن تظهر هذه الصفة في الأبناء", "تظهر في الإناث فقط", "هذه الصفة لا تنتقل عن طريق الوراثة", "يكون للأبناء جميعًا غمازات"]',0);
