INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',20,'الوراثة والصفات','المرحلة الثانية من دورة حياة الضفدع هي:','["ضفدع غير بالغ", "بيضة", "ضفدع مكتمل النمو", "أبو ذنيبة"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',20,'الوراثة والصفات','أيّ الأنماط التالية يُعدّ من أمثلة التكاثر اللاجنسي؟','["الانشطار الثنائي في البكتيريا", "الإخصاب الداخلي في الثدييات", "التزاوج في الطيور", "التلقيح في النباتات الزهرية"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',20,'الوراثة والصفات','مخلوق حي يستطيع إنتاج أبناء بصفات مختلفة:','["البكتيريا", "الهجين", "البدائيات", "الحامل للصفة النقية"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',20,'الوراثة والصفات','لتتبع الصفات الوراثية في العائلة ودراسة الأنماط الوراثية نستخدم:','["التلقيح الخلطي", "دورة الخلية", "الانتخاب الطبيعي", "مخطط السلالة"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'علوم',20,'الوراثة والصفات','الصفة الوراثية التي تمنع صفة أخرى من الظهور تسمى صفة:','["متنحية", "سائدة", "موروثة", "مكتسبة"]',1);
