INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',6,'العوامل والمضاعفات','يزرع ماجد 30 نبتة فاصوليا و45 نبتة بازلاء، ويريد أن يزرع العدد نفسه من النباتات في كل صف، بحيث يحتوي الصف على صنف واحد. فما أكبر عدد من النباتات يمكن أن يزرعه في كل صف؟','["10", "3", "15", "5"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',6,'العوامل والمضاعفات','أرادت ميسون توزيع 36 تفاحة و27 برتقالة على عدد من الصحون، بحيث يكون في كل صحن العدد نفسه من التفاح والعدد نفسه من البرتقال. ما أكبر عدد من الصحون؟','["6", "9", "3", "12"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',6,'العوامل والمضاعفات','يرتب ماجد 8 صور كبيرة و12 صورة متوسطة و16 صورة صغيرة في صفحات، بحيث يضع العدد نفسه من كل نوع في كل صفحة. ما أكبر عدد من الصفحات يمكن أن يستخدمه؟','["2", "8", "4", "6"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',6,'العوامل والمضاعفات','محمد وأحمد يقفزان على خط الأعداد بدءًا من الصفر؛ الأول يقفز كل 5 أرقام، والثاني كل 3 أرقام. كم مرة يلتقيان قبل العدد 100؟','["4", "6", "10", "9"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',6,'العوامل والمضاعفات','توفر أمل 8 ريالات أسبوعيًا، وتوفر هند 10 ريالات أسبوعيًا، وتدوّن كل منهما المبلغ الموجود في حصالتها أسبوعيًا. ما أول عدد مشترك تدوّنه البنتان؟','["24", "80", "32", "40"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',6,'العوامل والمضاعفات','قاعة فيها طاولات مربعة بأربعة أرجل وطاولات دائرية بثلاثة أرجل، ومجموع الأرجل 38. كم عدد الطاولات الدائرية إذا كانت تزيد بواحدة عن المربعة؟','["4", "6", "7", "5"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',7,'العوامل والمضاعفات','سلك معدني قُصّ إلى 4 قطع، طول كل قطعة ضعف طول التي قبلها. إذا كان طول السلك 60 سم، فكم يبلغ طول القطعة الأصغر؟','["15 سم", "4 سم", "2 سم", "8 سم"]',1);
