INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',8,'الكسور الاعتيادية','تناول فهد قطعة من البيتزا وأعطى الباقي لصديقيه حاتم وعلي بالتساوي كما في الرسم. كم من البيتزا سيأكل حاتم؟','["23", "24", "12", "38"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',8,'الكسور الاعتيادية','تريد ليلى أن تكتب تغريدة مكوّنة من 200 حرف، وإذا كان لا يُسمح بأكثر من 140 حرفًا في التغريدة الواحدة، فكم تغريدة تحتاج؟','["اثنتان", "واحدة ونصف", "واحدة", "اثنتان ونصف"]',0);
