INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',10,'القوى وترتيب العمليات','ذهبت عبير مع ثلاث من زميلاتها إلى مدينة الألعاب، فإذا دفعت كل منهن 7 ريالات ثمن تذكرة الدخول و3 ريالات ثمن قطعة حلوى وريالًا ثمن قارورة ماء، كم الثمن الذي دفعته عبير وزميلاتها؟','["50", "44", "60", "28"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',10,'القوى وترتيب العمليات','تقرأ مريم كتابًا، فقرأت في 5 أيام متتالية بمعدل 6 صفحات كل يوم، وفي اليومين التاليين كل يوم 3 صفحات، وبقيت 5 صفحات. كم عدد صفحات الكتاب؟','["41", "27", "44", "30"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',11,'القوى وترتيب العمليات','ذهبت أسرة مكوّنة من 5 أشخاص إلى رحلة بحرية ومعهم 520 ريالًا، فدفعوا عن كل واحد منهم 55 ريالًا لركوب السفينة و6 ريالات للصيد بالسنارة. فكم ريالًا بقي معهم؟','["330", "200", "150", "215"]',3);
