INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',11,'الأنماط والدوال','ما العدد المناسب في الفراغ: 2، 3، 5، 9، 17، ....، 65؟','["53", "43", "33", "23"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',11,'الأنماط والدوال','في الجدول، المخرجة = المدخلة − 8. ما المدخلة المناسبة في الفراغ؟','["10", "24", "11", "26"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',11,'الأنماط والدوال','إذا تكرر النمط الآتي (من اليمين إلى اليسار)، فما الشكل الذي سيكون رقمه 16؟','["🔺", "⭐", "🔵", "🟧"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','يبيّن الجدول معدل زيادة كتل الأطفال حديثي الولادة بحسب العمر بالشهور. كم يكون معدل كتل الأطفال عند بلوغ 5 أشهر؟','["7.00 كجم", "6.50 كجم", "6.75 كجم", "6.25 كجم"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','يضع بائع مجموعات من الطماطم في صحون صغيرة وفق الجدول. ما العلاقة بين عدد الصحون وعدد الطماطم؟','["عدد الطماطم = عدد الصحون + 4", "عدد الصحون = عدد الطماطم + 4", "عدد الطماطم = 4 × عدد الصحون", "عدد الصحون = 4 × عدد الطماطم"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','قاعدة الدالة الممثلة في الجدول هي:','["ص = 3س", "ص = 3س + 4", "ص = 3س + 1", "ص = 4س"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','قاعدة الدالة الممثلة في الجدول هي:','["س + 6", "س − 8", "س − 9", "س + 7"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','خزان فيه 100 لتر من الماء، يتدفق منه 3 لترات في كل دقيقة. كم يتبقى من الماء في الخزان بعد 11، 14، 17 دقيقة؟','["68، 58، 49", "67، 58، 48", "67، 58، 49", "67، 57، 49"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','إذا كانت قاعدة الدالة: ص = 3س − 1، فأيّ الأزواج المرتبة تحقق العلاقة؟','["(1، 14)، (2، 11)، (3، 8)", "(1، 2)، (2، 8)، (3، 10)", "(1، 5)، (2، 4)، (3، 3)", "(1، 2)، (2، 5)، (3، 8)"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',12,'الأنماط والدوال','يبيّن الجدول أطوال أربع أشجار في إحدى الحدائق. أيّ مما يلي يمثل أفضل تقدير للمجموع الكلي للأطوال؟','["14 م", "8 م", "15 م", "12 م"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',13,'الأنماط والدوال','عبدالله مهاجم متميز، يسجل الأهداف وفق القاعدة ص = 2س − 1، حيث س رقم المباراة. فإن مجموع أهدافه في المباريات الثلاث الأولى هو:','["1", "5", "3", "9"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',13,'الأنماط والدوال','انطلق أحمد وخالد في سباق دراجات، وكانت المسافة بينهما تتزايد كل دقيقة كما في الجدول. فكم مترًا تكون المسافة بينهما بعد مرور 10 دقائق؟','["50", "30", "40", "20"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',13,'العبارات الجبرية والمعادلات','من دون حساب، إذا كانت ن = 8، فما الفرق بين قيمة العبارة 3ن والعبارة ن + ن؟','["3ن تساوي ن + ن", "لا يمكن معرفة الفرق", "3ن أصغر من ن + ن", "3ن أكبر من ن + ن"]',3);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'رياضيات',13,'العبارات الجبرية والمعادلات','في إحدى المدارس يزيد عدد طلاب الصف الخامس 6 طلاب على عدد طلاب الصف السادس. إذا كان طلاب الصف السادس 21 طالبًا، فما عدد طلاب الصف الخامس؟','["6 + ع = 26", "21 − 6 = 15", "21 − ع = 12", "21 + 6 = 27"]',3);
