INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'لغتي',27,'يميّز المفردات المتشابهة في المعنى ويوظفها في جمل','«كان أحمد يشعر بالفرح وهو يستكشف العناوين» الكلمة التي تعني (السرور) في النص:','["الفرح", "الحزن", "الضجر", "القلق"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'لغتي',27,'يميّز المفردات المتشابهة في المعنى ويوظفها في جمل','أيّ جملة تعبّر عن (استغلال الوقت)؟','["أحمد يعود إلى المنزل مسرعًا", "أحمد يشاهد الأطفال يلعبون", "أحمد يقرأ كتابًا في أوقات فراغه", "أحمد ذهب إلى المكتبة"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'لغتي',27,'يميّز المفردات المتشابهة في المعنى ويوظفها في جمل','جاءت كلمة (مفيد) بمعنى (نافع)؛ الجملة التي تناسب هذا المعنى:','["تناول الطعام الصحي مفيد للجسم والعقل", "مفيد طالب مجتهد", "اللعب كثيرًا غير مفيد", "ذهبت إلى مكان مفيد"]',0);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'لغتي',27,'يميّز المفردات المتشابهة في المعنى ويوظفها في جمل','كلمة (يذود) بمعنى (يدافع)؛ الجملة التي تناسب المعنى من نص أبي بكر الصديق:','["يذود عن صديقه", "يذود عن دينه", "يذود عن النبي ﷺ", "يذود عن عرينه"]',2);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'لغتي',27,'يميّز المفردات المتشابهة في المعنى ويوظفها في جمل','أيّ الجمل تحتوي على استخدام صحيح لكلمة (فاعلية) أو أحد مرادفاتها؟','["الكمامات بطيئة العمل", "أثبتت الكمامات كفاءتها في الحد من انتشار الأمراض", "سوء استخدام الكمامات يجعلها بلا فائدة", "الكمامات ضعيفة التأثير"]',1);
INSERT INTO questions(grade,subject,week,lesson,question,choices_json,answer_index) VALUES (6,'لغتي',27,'يميّز المفردات المتشابهة في المعنى ويوظفها في جمل','أيّ الجمل تحمل المعنى الصحيح لكلمة (أهداف)؟','["للرؤية نظريات عظيمة", "للرؤية سمات واضحة", "للرؤية أعمال جليلة", "للرؤية غايات طموحة"]',3);
